fn material(in: MaterialIn) -> vec4<f32> {
  return vec4<f32>(in.color.rgb * (0.5 + 0.5 * in.value), 1.0);
}

@group(0) @binding(0) var<storage, read> w: array<f32>;
@group(0) @binding(1) var<storage, read_write> positions: array<f32>;
@group(0) @binding(2) var<storage, read_write> count: atomic<u32>;
@compute @workgroup_size(64) fn run(@builtin(global_invocation_id) id: vec3<u32>) {
  let i = id.x;
  if (i >= 256u) { return; }
  positions[3u * i] = w[3u * i];
  positions[3u * i + 1u] = w[3u * i + 1u];
  positions[3u * i + 2u] = w[3u * i + 2u];
  atomicAdd(&count, 1u);
}

